from tinygrad.nn.state import get_state_dict


class Inner:
    def __init__(self):
        self.w = T(np.ones((4, 32), np.float32))


class Model:
    def __init__(self):
        self.inner = Inner()
        self.b = T(np.zeros(32, np.float32))
        self.i = Tensor(np.arange(4, dtype=np.int32), device="KTPU")


def facts():
    m = NN.place(Model())
    return {k: [t.dtype.name, t.device] for k, t in get_state_dict(m).items()}
